<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;url&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;https://saas.example.net/mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
